"""Seal this completed run; compare a fresh reproduction and historical fingerprints."""
from pathlib import Path
import hashlib,json,sys,platform,subprocess,shutil
from datetime import datetime,timezone
import numpy,pandas,matplotlib,sklearn,scipy
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def dump(p,v):p.write_text(json.dumps(v,indent=2,allow_nan=False)+'\n')
if (HERE/'manifest.json').exists():raise ValueError('Final manifest already exists; refuse resealing')
repro=HERE/'reproduction_check';reproduced={}
for p in sorted(repro.iterdir()):
 if p.is_file():
  assert (HERE/p.name).is_file(),p
  assert sha(p)==sha(HERE/p.name),'Nonidentical reproduced output: '+p.name
  reproduced[p.name]=sha(p)
dump(HERE/'reproduction_verification.json',dict(Status='passed',FreshRun='analyze.py --out '+str(repro.relative_to(ROOT)),ByteIdenticalOutputs=reproduced,TemporaryDuplicateOutputsRemovedAfterComparison=True))
shutil.rmtree(repro)
# Run the overwrite guard and retain its exact rejection, without touching any result.
check=subprocess.run([sys.executable,str(HERE/'analyze.py')],cwd=ROOT,capture_output=True,text=True)
assert check.returncode!=0 and 'Results already exist' in check.stderr
(HERE/'logs/overwrite_guard.txt').write_text(check.stdout+check.stderr)
original=json.loads((HERE/'preservation_before.json').read_text());changed=[p for p,w in original.items() if not (ROOT/p).is_file() or sha(ROOT/p)!=w];assert not changed,changed
sources=json.loads((HERE/'source_hashes.json').read_text());assert all(sha(ROOT/p)==w for p,w in sources.items())
dump(HERE/'preservation_check.json',dict(Status='passed',PreexistingFilesChecked=len(original),ChangedFiles=changed,SourceArtifactsRechecked=len(sources),TrackedDiffEmpty=not subprocess.check_output(['git','diff','--name-only'],cwd=ROOT,text=True).strip()))
outputs={str(p.relative_to(HERE)):dict(SHA256=sha(p),Bytes=p.stat().st_size) for p in sorted(HERE.rglob('*')) if p.is_file() and '__pycache__' not in str(p) and p.name!='manifest.json'}
commands=[dict(Command='MPLCONFIGDIR=/tmp/ppg-leadtime-mpl XDG_CACHE_HOME=/tmp/ppg-leadtime-cache '+sys.executable+' '+str(HERE.relative_to(ROOT))+'/analyze.py',Purpose='Initial analysis and corrected integer-count regeneration',Status='completed'),dict(Command=sys.executable+' -m unittest discover -s '+str(HERE.relative_to(ROOT))+'/tests -v',Result='6/6 passed after correcting new CSV integer counts'),dict(Command=sys.executable+' -m unittest experiments.incremental_value_20261027.test_study experiments.final_audit_20261027T215012_IST.tests.test_audit tests.test_alarm_budget tests.test_reliability -v',Result='67 run: 66 passed, one unrelated missing historical artifact error'),dict(Command=sys.executable+' '+str(HERE.relative_to(ROOT))+'/analyze.py --out '+str(repro.relative_to(ROOT)),Result='fresh run; all '+str(len(reproduced))+' outputs byte-identical; duplicate files removed'),dict(Command=sys.executable+' '+str(HERE.relative_to(ROOT))+'/build_report.py',Result='report/claims/README generated from final tables'),dict(Command=sys.executable+' -m compileall -q '+str(HERE.relative_to(ROOT)),Result='passed'),dict(Command=sys.executable+' '+str(HERE.relative_to(ROOT))+'/analyze.py',Purpose='Overwrite-guard check after completion',Result='rejected existing results as expected'),dict(Command=sys.executable+' '+str(HERE.relative_to(ROOT))+'/finalize.py',Result='preservation, reproduction and hash seal completed')]
dump(HERE/'manifest.json',dict(Study='Frozen models: incremental PPG warning lead-time comparison',Status='completed_with_documented_validation_limits',CompletedUTC=datetime.now(timezone.utc).isoformat(),DisplayTimezone='Asia/Calcutta',Repository=str(ROOT),SourceExperiment='experiments/incremental_value_20261027',SourceHashes=sources,Parameters=dict(Recordings=list(range(1,31)),Models=['Logistic','GaussianNB','ELM'],Modalities=['SpO2_history','Combined'],Horizon_s=30,ThresholdPolicy='unchanged fold-specific training OOF maximum detections subject to starts<=5/evaluable hour and active fraction<=0.05',EventDefinitions=['original','sustained3'],Matching='chronological earliest unused actual episode start in [onset-30,onset)',MinimumLeadRequirements_s=[0,5,10,15,20,30],BootstrapReplicates=2000,BootstrapSeed=20261027,BootstrapUnit='whole recordings, paired multiplicities; no refits',EligibleOriginalEvents=14,OriginalEventRecordings=6,EligibleSustainedEvents=13,SustainedEventRecordings=5,LogisticPairedEvents=7,LogisticPairedRecordings=4),Software=dict(Python=sys.version,Numpy=numpy.__version__,Pandas=pandas.__version__,Matplotlib=matplotlib.__version__,ScikitLearn=sklearn.__version__,Scipy=scipy.__version__,Platform=platform.platform()),Commands=commands,Tests=dict(FocusedPassed=6,FocusedRun=6,ExistingRun=67,ExistingPassed=66,ExistingErrors=1,MissingHistoricalArtifact='results/final/future_low/causal_dataset.csv',FullRepositorySuiteRun=False),Preservation=dict(Checked=len(original),Changed=0,ModelsRefitted=False,ThresholdsRetuned=False,DatasetExpanded=False),Unavailable=['post-onset alarm response latency under the existing preonset rule','timestamped acknowledgement/intervention/device/flow delivery logs','clinical outcomes','valid human PPG reference annotations','verified independent patient IDs'],Deviations=['No scientific protocol changes','Late/at-onset warning latency unavailable under preserved current-normal preonset rule; explicitly not fabricated','No new matching sensitivity: valid existing convention used','Legacy artifact test error retained without reconstructing missing data'],FreshReproductionByteIdentical=True,Outputs=outputs,ManifestSelfHashExcluded=True))
